import React, { Fragment } from 'react';
import { useIntl } from 'react-intl';
import styled from 'styled-components';

import Colors from '@dynatrace/strato-design-tokens/colors';
import Spacings from '@dynatrace/strato-design-tokens/spacings';
import Text from '@dynatrace/strato-design-tokens/typography';

import { Flex } from '../../../../layouts-core/flex/Flex.js';
import { Divider } from '../../../../typography/Divider.js';
import { Text as Text2 } from '../../../../typography/Text.js';
import { ChartActionsMenu } from '../../../core/components/series-action/ChartActionsMenu.js';
import { mergeTooltipActions } from '../../../core/components/series-action/functions/mergeTooltipActions.js';
import { useChartActionsMenu } from '../../../core/components/series-action/hooks/useChartActionsMenu.js';
import { InteractiveChartTooltip } from '../../../core/components/tooltip/InteractiveChartTooltip/components/InteractiveChartTooltip.js';
import { TooltipActionTemplate } from '../../../core/components/tooltip/shared/hooks/useTooltipSeriesActions.js';
import { MouseCoordinate } from '../../../core/types/overlays.js';
import { TooltipItem } from '../../../core/types/tooltip.js';
import { WithId } from '../../../core/types/with-id.js';
import { useHistogramAnnotationsConfig } from '../../hooks/useHistogramAnnotationsConfig.js';
import { useHistogramXFormatter } from '../../hooks/useHistogramXFormatter.js';
import { HISTOGRAM_MESSAGES } from '../../messages/tooltip-text.js';
import {
  HistogramAnnotationsMarkerProps,
  isHistogramValueAnnotation,
} from '../../types/histogram-annotations.js';

interface HistogramAnnotationsTooltipProps {
  tooltipRef: React.Ref<HTMLDivElement> | undefined;
  position: MouseCoordinate;
  pinned: boolean;
  markersGroup: WithId<HistogramAnnotationsMarkerProps>[][];
  onItemHover: (id: string) => void;
  onItemLeave: () => void;
}

const SubduedText: typeof Text2 = /* @__PURE__ */ styled(Text2)({
  color: Colors.Text.Neutral.Subdued,
});

const HeaderWrapper = /* @__PURE__ */ styled('div')({
  padding: Spacings.Size8,
  paddingBottom: Spacings.Size4,
});

const DividerWrapper = /* @__PURE__ */ styled('div')({
  paddingLeft: Spacings.Size8,
  paddingRight: Spacings.Size8,
});

const BodyWrapper = /* @__PURE__ */ styled('div')({
  padding: Spacings.Size8,
  paddingTop: Spacings.Size4,
});

const StyledTooltipItemContent = /* @__PURE__ */ styled(Flex)({
  alignItems: 'center',
  padding: `${Spacings.Size4} ${Spacings.Size4} ${Spacings.Size0} ${Spacings.Size4}`,
  width: '100%',
  '&:hover': {
    backgroundColor: Colors.Background.Base.Default,
    cursor: 'pointer',
  },
});

const StyledSymbol = /* @__PURE__ */ styled('div')({
  padding: `0 ${Spacings.Size4}`,
  width: '18px',
  textAlign: 'center',
});

const StyledSymbolContainer = /* @__PURE__ */ styled('div')({
  padding: '0',
  flex: '0 0 30px',
});

const StyledTextContainer = /* @__PURE__ */ styled('div')<{
  emphasized: boolean;
}>(({ emphasized }) => ({
  fontWeight: `${
    emphasized
      ? Text.Text.Base.Emphasized.Weight
      : Text.Text.Base.Default.Weight
  }`,
}));

const ESTIMATED_ACTION_HEIGHT = 35;

export const HistogramAnnotationsTooltip = (
  props: HistogramAnnotationsTooltipProps,
) => {
  const {
    pinned,
    tooltipRef,
    position,
    markersGroup,
    onItemHover,
    onItemLeave,
  } = props;
  const config = useHistogramAnnotationsConfig();
  const {
    selectedItem,
    updateSelectedItem,
    actionsMenuRef,
    onLeave: handleMenuLeave,
  } = useChartActionsMenu();
  const intl = useIntl();
  const formatter = useHistogramXFormatter();

  const handleMouseLeave = (event: React.MouseEvent) => {
    handleMenuLeave(event);
  };

  const getTitle = (marker: HistogramAnnotationsMarkerProps) => {
    if (isHistogramValueAnnotation(marker.value)) {
      return `${intl.formatMessage(
        HISTOGRAM_MESSAGES.annotationsTooltipTitleValue,
      )}: ${formatter(marker.value)}`;
    }

    return `${intl.formatMessage(
      HISTOGRAM_MESSAGES.annotationsTooltipTitleValueRange,
    )}: ${formatter(marker.value.from)} – ${formatter(marker.value.to)}`;
  };

  const getTooltipItem = (marker: WithId<HistogramAnnotationsMarkerProps>) => {
    return {
      ...marker,
      name: marker.title,
    } as unknown as TooltipItem;
  };

  const seriesActions = config?.annotationsActions;

  const seriesActionsCallback = (
    marker: WithId<HistogramAnnotationsMarkerProps>,
  ) =>
    mergeTooltipActions(
      getTooltipItem(marker),
      seriesActions as unknown as TooltipActionTemplate,
    );

  return (
    <InteractiveChartTooltip
      pinned={pinned}
      ref={tooltipRef}
      position={position}
      itemSize={() => ESTIMATED_ACTION_HEIGHT}
      onMouseLeave={handleMouseLeave}
    >
      <InteractiveChartTooltip.Body>
        {markersGroup?.map((sameValueGroup, index) => (
          <Fragment key={`tooltip-${sameValueGroup[0].id}`}>
            <HeaderWrapper data-testid="histogram-annotation-tooltip">
              <SubduedText textStyle="small">
                {getTitle(sameValueGroup[0])}
              </SubduedText>
            </HeaderWrapper>
            {sameValueGroup.map((marker) => {
              return (
                <ChartActionsMenu
                  key={`content-${marker.id}`}
                  isOpen={selectedItem === marker.id}
                  ref={actionsMenuRef}
                  actions={() => seriesActionsCallback(marker)()}
                >
                  <BodyWrapper
                    onMouseOver={() => {
                      updateSelectedItem(marker.id);
                      onItemHover(marker.id);
                    }}
                    onMouseLeave={onItemLeave}
                  >
                    <StyledTooltipItemContent>
                      {marker.symbol && (
                        <StyledSymbolContainer>
                          <StyledSymbol>{marker.symbol}</StyledSymbol>
                        </StyledSymbolContainer>
                      )}
                      <StyledTextContainer
                        emphasized={marker.id === selectedItem}
                      >
                        <Text2 textStyle="small-emphasized" as="p">
                          {marker.title}
                        </Text2>
                        <SubduedText textStyle="small" as="p">
                          {marker.description}
                        </SubduedText>
                      </StyledTextContainer>
                    </StyledTooltipItemContent>
                  </BodyWrapper>
                </ChartActionsMenu>
              );
            })}
            {index !== markersGroup.length - 1 && (
              <DividerWrapper key={`divider-${sameValueGroup[0].id}`}>
                <Divider />
              </DividerWrapper>
            )}
          </Fragment>
        ))}
      </InteractiveChartTooltip.Body>
    </InteractiveChartTooltip>
  );
};
